class Solution {
  private boolean[] onPath;
  private int[] digits;
  private long[][] memo;

  private long dfs(int pos, int last, boolean tight) {
    if (pos == 16) return 1;
    if (!tight && memo[pos][last] >= 0) return memo[pos][last];
    int limit = tight ? digits[pos] : 9;
    long res = 0;
    for (int d = 0; d <= limit; d++) {
      if (onPath[pos]) {
        if (d < last) continue;
        res += dfs(pos + 1, d, tight && d == limit);
      } else {
        res += dfs(pos + 1, last, tight && d == limit);
      }
    }
    if (!tight) memo[pos][last] = res;
    return res;
  }

  private long count(long n) {
    if (n < 0) return 0;
    String s = String.format("%016d", n);
    digits = new int[16];
    for (int i = 0; i < 16; i++) digits[i] = s.charAt(i) - '0';
    memo = new long[16][10];
    for (long[] row : memo) java.util.Arrays.fill(row, -1);
    return dfs(0, 0, true);
  }

  public long countGoodIntegersOnPath(long l, long r, String directions) {
    onPath = new boolean[16];
    int row = 0, col = 0;
    onPath[0] = true;
    for (char c : directions.toCharArray()) {
      if (c == 'D') row++;
      else col++;
      onPath[row * 4 + col] = true;
    }
    return count(r) - count(l - 1);
  }
}
